			AND receiver_id <> `+deleteUserPlaceholder(2), userID, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	inboxIDs := make([]int32, 0)
	for rows.Next() {
		var (
			inboxID    int32
			messageRaw []byte
		)
		if err := rows.Scan(&inboxID, &messageRaw); err != nil {
			return nil, err
		}
		if len(messageRaw) == 0 {
			continue
